function ownedQuery(principal) {
  if (!principal || !principal.userId || !principal.tenantId) return { error: 'unauthenticated' };
  return { where: { ownerId: principal.userId, tenantId: principal.tenantId } };
}
const alice = { userId: 'u-a', tenantId: 't-1' };
console.log(JSON.stringify(ownedQuery(alice)));
console.log(JSON.stringify(ownedQuery(null)));
console.log(JSON.stringify(ownedQuery({ userId: 'u-b' })));
console.log('cross-read prevented: ' + (ownedQuery(alice).where.ownerId !== 'u-b'));

